ALTER TABLE public.profiles ADD COLUMN glucose_target_min integer NOT NULL DEFAULT 120, ADD COLUMN glucose_target_max integer NOT NULL DEFAULT 180, ADD COLUMN glucose_rescue_grams integer NOT NULL DEFAULT 15; ALTER TABLE public.profiles ADD CONSTRAINT profiles_glucose_target_min_check CHECK (glucose_target_min BETWEEN 60 AND 200), ADD CONSTRAINT profiles_glucose_target_max_check CHECK (glucose_target_max BETWEEN 100 AND 300), ADD CONSTRAINT profiles_glucose_target_order CHECK (glucose_target_min < glucose_target_max), ADD CONSTRAINT profiles_glucose_rescue_check CHECK (glucose_rescue_grams BETWEEN 5 AND 60);